def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_defects = 0
    my_defects = 0
    for me, opp in history:
        if opp == 'D':
            opp_defects += 1
        if me == 'D':
            my_defects += 1

    last_me, last_opp = history[-1]

    # Endgame: defect aggressively
    if n >= 95:
        return 'D'

    # Apology phase: if we defected two rounds ago and cooperated last round,
    # but opponent still defected last round, cooperate again to restore.
    if n >= 2:
        if history[-2][0] == 'D' and history[-1][0] == 'C' and history[-1][1] == 'D':
            return 'C'

    # If opponent has never defected, we are in a cooperative match.
    if opp_defects == 0:
        if n < 10:
            return 'C'
        if n % 5 == 0:
            return 'D'
        if n >= 90 and n % 2 == 0:
            return 'D'
        return 'C'

    # Opponent has defected at least once.
    if last_opp == 'D':
        if opp_defects <= 2 and n > 10:
            if rng.random() < 0.2:
                return 'C'
        return 'D'
    else:
        if last_me == 'D':
            return 'C'
        if opp_defects * 2 > n:
            return 'D'
        return 'C'
